X("newsfeed-hld",
  P("""**What the system does.** When you open the app you see a ranked list of recent posts from people and pages you follow, in under ~200 ms. The central decision is **when to assemble each feed**: when a post is written (**fan-out on write / push**) or when a feed is read (**fan-out on read / pull**). Real systems use a **hybrid**."""),
  AN("Push is like a newspaper delivered to every subscriber's door the moment it's printed: reading is instant, but a paper with 100 million subscribers takes forever to deliver. Pull is like going to each author's shop when you want to read: no delivery cost, but slow if you follow 500 shops. The hybrid: deliver normal authors' posts, and visit the few celebrity shops yourself."),
  CALC("Sizing", [("Feed reads per second", "r = 300e6 * 10 / 86400", "/s"), ("Peak reads", "r * 3", "/s"), ("New posts per second", "w = 300e6 / 86400", "/s"),
                  ("Feed-cache writes per second (avg 200 followers, push)", "w * 200", "/s"), ("Feed cache memory (500 ids × 8 B × 300 M users)", "500 * 8 * 300e6", "B")]),
  SEQ("Writing a post (push for normal users)", ["Author", "Post service", "Kafka", "Fan-out worker", "Social graph", "Feed cache"],
      [["Author", "Post service", "POST /posts"], ["Post service", "Post service", "store in Posts DB, id = Snowflake"], ["Post service", "Kafka", "PostCreated{id, author}", "a"],
       ["Fan-out worker", "Social graph", "followers(author)", "", "If the author has > ~10k followers (celebrity), skip push entirely."],
       ["Fan-out worker", "Feed cache", "LPUSH feed:{f} postId; LTRIM 0 499", "", "For each **active** follower only (inactive users' feeds are built on demand). Keep the latest 500 ids."]]),
  SEQ("Reading the feed (merge + rank + hydrate)", ["User", "Feed service", "Feed cache", "Celebrity posts", "Ranking", "Post cache"],
      [["User", "Feed service", "GET /feed?cursor="], ["Feed service", "Feed cache", "LRANGE feed:{me} 0 499", "", "Precomputed ids from normal friends."],
       ["Feed service", "Celebrity posts", "recent posts of the celebrities I follow", "", "Pulled at read time: a few lists, each cached."], ["Feed service", "Ranking", "score(candidates)", "", "ML model: affinity with author, recency, predicted engagement."],
       ["Feed service", "Post cache", "hydrate top 20 ids → text, media URLs, counts"], ["Feed service", "User", "20 posts + next cursor", "r", "Cursor = last post id/score, not page numbers (stable as new posts arrive)."]]),
  TABLE("Push vs pull vs hybrid", ["", "Fan-out on write (push)", "Fan-out on read (pull)", "Hybrid"],
        [["Read latency", "very fast", "slow (merge many lists)", "fast"], ["Write cost", "followers × 1", "1", "normal users only"], ["Celebrity post", "millions of writes", "cheap", "pulled"], ["Inactive users", "wasted work", "no cost", "build on demand"]]))

